from threetears.evals import Eval

from digest import digest_file


def summarise(case):
    """The digest of the case's report."""
    return {"digest": digest_file("data/" + case["report"])}


def carries_most_facts(case, out):
    """The digest carries at least half the key facts the head of operations listed for the report."""
    carried = sum(fact in out["digest"] for fact in case["facts"])
    return carried * 2 >= len(case["facts"])


reports = Eval("data/key_facts.jsonl", runner=summarise, grader=[carries_most_facts], k=1)
